target.css:
:root {
  --bg: #3b1a08;
  --surface: #fdf5e6;
  --border: #8b4513;
  --accent: #7a1c2e;
  --gold: #c8922a;
  --text-primary: #2a0e04;
  --text-secondary: #6b3a1f;
  --text-muted: #9e6b45;
  --divider: #d4a96a;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
}

.wine-tag {
  background-color: var(--surface);
  border: 3px solid var(--border);
  border-radius: 6px;
  width: 260px;
  padding: 20px 24px;
  outline: 2px solid var(--gold);
  outline-offset: -8px;
}

.tag-header {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin-bottom: 12px;
}

.tag-year {
  font-size: 13px;
  font-weight: 700;
  color: var(--accent);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.tag-divider {
  font-size: 11px;
  color: var(--gold);
}

.tag-type {
  font-size: 13px;
  font-weight: 700;
  color: var(--accent);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.tag-name {
  font-size: 22px;
  font-weight: 800;
  color: var(--text-primary);
  text-align: center;
  margin: 0 0 6px 0;
  line-height: 1.2;
}

.tag-region {
  font-size: 12px;
  color: var(--text-muted);
  text-align: center;
  letter-spacing: 0.05em;
  margin: 0 0 16px 0;
}

.tag-footer {
  display: flex;
  justify-content: space-between;
  border-top: 1px solid var(--divider);
  padding-top: 12px;
  gap: 8px;
}

.tag-stat {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.stat-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.07em;
}

.stat-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-secondary);
}

